import os,re
from collections import Counter,deque
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def components(g,bg):
    h,w=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    rr,cc=q.popleft(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=rr+dr,cc+dc
                        if 0<=a<h and 0<=b<w and g[a][b]!=bg and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                comps.append(cells)
    return comps

def largest_solid_rect(cells):
    cells=set(cells)
    best=None
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    for r0 in range(min(rs),max(rs)+1):
        for r1 in range(r0,max(rs)+1):
            for c0 in range(min(cs),max(cs)+1):
                for c1 in range(c0,max(cs)+1):
                    if all((r,c) in cells for r in range(r0,r1+1) for c in range(c0,c1+1)):
                        a=(r1-r0+1)*(c1-c0+1)
                        if best is None or a>best[0]: best=(a,r0,r1,c0,c1)
    return best

def f(g):
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0]); o=[row[:] for row in g]
    for cells in components(g,bg):
        if len(cells)<=2: continue
        L=largest_solid_rect(cells)
        a,r0,r1,c0,c1=L
        if a>=0.5*len(cells):  # solid mode
            cs=set(cells)
            for (r,c) in cells:
                if not (r0<=r<=r1 and c0<=c<=c1): o[r][c]=2
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if g[r][c]==bg: o[r][c]=2
        else:  # outline mode
            rs=[r for r,_ in cells]; cs=[c for _,c in cells]
            R0,R1,C0,C1=min(rs),max(rs),min(cs),max(cs)
            perim=lambda r,c: r in(R0,R1) and C0<=c<=C1 or c in(C0,C1) and R0<=r<=R1
            for r in range(R0,R1+1):
                for c in range(C0,C1+1):
                    if g[r][c]==bg and perim(r,c): o[r][c]=2
            # inner full-span lines
            for c in range(C0+1,C1):
                colr=[r for (rr,cc) in cells if cc==c]
                if colr and min(colr)==R0 and max(colr)==R1:
                    for r in range(R0,R1+1):
                        if g[r][c]==bg: o[r][c]=2
            for r in range(R0+1,R1):
                rowc=[c for (rr,cc) in cells if rr==r]
                if rowc and min(rowc)==C0 and max(rowc)==C1:
                    for c in range(C0,C1+1):
                        if g[r][c]==bg: o[r][c]=2
    return o

for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    i,o=G[k+' input'],G[k+' output']; mine=f(i)
    diff=[(r,c,mine[r][c],o[r][c]) for r in range(len(i)) for c in range(len(i[0])) if mine[r][c]!=o[r][c]]
    print(k,'diffs:',diff)
out=f(G['Test input'])
print('test changes:',[(r,c,out[r][c]) for r in range(29) for c in range(12) if out[r][c]!=G['Test input'][r][c]])
for row in out[18:26]: print(''.join(map(str,row)))

